('ff59fc64-eaf5-4631-9e2e-914503249a17'::uuid,'412ef32e-ee64-44d8-82ce-498f1b537897'::uuid,34220659,'f554a208b9437edebcedc616f9d5cb386250d934ee49c0d09088911ad7d7b5c6','65ef412def2c2beef92c56ffa9989a4b','374bc026fd9374e9fd45e8d97f35905d','c94834f2cd10c8b632771cf54fe0f321','b25083ca07bcb46511a49c8ffb0e2e70','229ee7a1-a1b6-4ba9-8d9a-5ae12571f402'::uuid,'059ed845adb72342e462f4283216b0d7','f54e4fb4-ecab-4ebc-8a33-616c5cd7c650'::uuid,'fade0000-0000-0000-0000-000000000001'::uuid,'fade0000-0000-0000-0000-000000000001'::uuid))v(submission_id,table_id,hand_number,request_hash,submission_md5,request_md5,handoff_md5,result_md5,permit_id,permit_md5,tournament_id,club_id,union_id) WHERE submission_id=e;
 IF NOT FOUND THEN RETURN NULL;END IF;
 SELECT * INTO s FROM smarter_private.hand_submissions WHERE submission_id=e;
 SELECT * INTO h FROM smarter_private.hand_submission_handoffs WHERE submission_id=e;
 SELECT * INTO z FROM smarter_private.hand_submission_handoff_results WHERE submission_id=e;
 SELECT * INTO p FROM smarter_private.f06_hand_permits WHERE permit_id=x.permit_id;
 stack_hand:=md5('ca-hand:'||s.table_id::text||':'||s.hand_number::text||CASE WHEN coalesce(s.request->>'p_ref','')='' THEN '' ELSE ':'||(s.request->>'p_ref') END)::uuid;
