 OR encode(sha256(convert_to(s.request::text,'UTF8')),'hex') IS DISTINCT FROM s.request_hash
 OR md5(to_jsonb(s)::text) IS DISTINCT FROM x.submission_md5 OR md5(s.request::text) IS DISTINCT FROM x.request_md5
 OR md5(to_jsonb(h)::text) IS DISTINCT FROM x.handoff_md5 OR md5(to_jsonb(z)::text) IS DISTINCT FROM x.result_md5
 OR md5(to_jsonb(p)::text) IS DISTINCT FROM x.permit_md5
 OR h.original_generation IS DISTINCT FROM s.lease_generation OR h.request_hash IS DISTINCT FROM s.request_hash
 OR z.result->>'reason' IS DISTINCT FROM 'rolled_back' OR z.result->>'error' IS DISTINCT FROM 'record "new" has no field "metadata"'
 OR z.result->'success' IS DISTINCT FROM 'false'::jsonb OR z.result->'atomic_hand_commit' IS DISTINCT FROM 'false'::jsonb
 OR p.state IS DISTINCT FROM 'reserved' OR p.table_id IS DISTINCT FROM s.table_id OR p.hand_number IS DISTINCT FROM s.hand_number
 OR p.generation IS DISTINCT FROM s.lease_generation OR p.tournament_id IS DISTINCT FROM x.tournament_id
 OR (s.request#>>'{p_hand_row,tournament_id}')::uuid IS DISTINCT FROM p.tournament_id
 OR NOT EXISTS(SELECT FROM public.tables tb JOIN public.tournaments t ON t.id=tb.tournament_id
   WHERE tb.id=s.table_id AND tb.tournament_id=x.tournament_id AND tb.club_id IS NOT DISTINCT FROM x.club_id
    AND tb.union_id IS NOT DISTINCT FROM x.union_id AND upper(t.status)='RUNNING' AND lower(tb.status) IN ('running','waiting') AND NOT coalesce(tb.is_deleted,false))
 OR EXISTS(SELECT FROM smarter_private.hand_submission_correction_claims WHERE submission_id=e)
 OR EXISTS(SELECT FROM smarter_private.hand_submission_disposals WHERE submission_id=e)
 OR EXISTS(SELECT FROM public.hand_atomic_commits WHERE table_id=s.table_id AND hand_number>=s.hand_number)
 OR EXISTS(SELECT FROM public.hand_history WHERE table_id=s.table_id AND hand_number>=s.hand_number)
 OR EXISTS(SELECT FROM smarter_private.f06_hand_permits WHERE table_id=s.table_id AND hand_number>s.hand_number)
 OR EXISTS(SELECT FROM public.hand_projection_outbox WHERE hand_id=e)
