('f80c0da6-826a-4836-bff1-ae0f1c26402d'::uuid,'102b5fd719640a32b8d7edf61a361f19','a38fcc97ab09e04b4d0be9863e11e0fe',2),
('f92a4e85-8462-4813-920f-fcfdecef5a2e'::uuid,'4ba0c97e7ffaa8ec13e40692f81875ca','5245aec4f604a9adde6173e379140a0a',2),
('fb754927-adc8-4b32-a031-f77ead3e8374'::uuid,'70f4087381d23f3e05a70854f8a4b0e6','f685cc36e843238202590f915d6ad804',2),
('fbb909ad-3d8f-480d-a4bb-2cf47411aa1c'::uuid,'b569f38efd83e2d20efb2e3e82a9bb41','a1bc37bbc2fe63fd8a9dcb0a09008989',2),
('febd1859-defa-41e9-981a-70cd68162a2e'::uuid,'a5310649cf437327eea3713e95cbf8fa','bd030f15179df9efa4a7e5e4697af1b9',2),
('ff59fc64-eaf5-4631-9e2e-914503249a17'::uuid,'b4f28248bda72633979a73180984007a','8e852a82754fe08d6f1b53544be2eb1e',2)
 ) f(submission_id,key_md5,settlement_md5,expected_attempt)
 JOIN public.settlement_idempotency_keys k ON k.table_id=s.table_id AND k.hand_id=stack_hand
 JOIN public.ca_settlements c ON c.settlement_type='hand_stacks' AND c.external_ref=s.table_id::text||':'||stack_hand::text
 WHERE f.submission_id=e AND md5(to_jsonb(k)::text)=f.key_md5 AND md5(to_jsonb(c)::text)=f.settlement_md5
 AND k.status='failed' AND k.attempt_count=f.expected_attempt AND k.completed_at IS NULL AND k.result IS NULL AND k.error='record "new" has no field "metadata"'
 AND c.table_id=s.table_id AND c.hand_id=stack_hand AND c.idempotency_key='hand:'||s.table_id::text||':'||stack_hand::text AND c.state='failed' AND c.totals='{}'::jsonb AND c.error_detail='record "new" has no field "metadata"')
 OR NOT EXISTS(SELECT FROM supabase_migrations.schema_migrations WHERE version='20261013133012'
  AND name='scoped_launch_operator_accepts_authoritative_json_claims' AND cardinality(statements)=1
  AND encode(sha256(convert_to(statements[1],'UTF8')),'hex')='89b1671cf9aa507248b7620f734855fa03cdf586d133a1caa9890530fbd04df3')
 OR (SELECT count(*)=3 AND bool_and((pg_get_userbyid(q.proowner)='postgres' AND q.prosecdef AND q.proacl::text='{postgres=X/postgres}' AND q.proconfig=ARRAY['search_path=public'] AND md5(pg_get_functiondef(q.oid))=v.postimage) IS TRUE)
  FROM (VALUES ('public.fn_cancelled_tournament_evidence_is_immutable()','c361537b74dd7b12f05cc58bd0d2ef4f'),('public.fn_satellite_transfer_ledger_is_immutable()','b4012023e95bf3ee041776a03bd2d731'),('public.fn_terminal_tournament_evidence_is_immutable()','1b3ab2bd7823977943d1baa0816997d0'))v(signature,postimage)
  LEFT JOIN pg_proc q ON q.oid=to_regprocedure(v.signature)) IS DISTINCT FROM true
 THEN RETURN NULL;END IF;
 RETURN jsonb_build_object('submission_id',e,'table_id',s.table_id,'hand_number',s.hand_number,'request_hash',s.request_hash,
 'request_md5',x.request_md5,'handoff_md5',x.handoff_md5,'result_md5',x.result_md5,'original_generation',s.lease_generation,
 'permit_id',p.permit_id,'source_cause','launch_typed_row_metadata','source_version','20261013133012',
 'source_sha256','89b1671cf9aa507248b7620f734855fa03cdf586d133a1caa9890530fbd04df3',
 'proof_version','20261013180855','scope','tournament');
END $body$;
